with tempfile.TemporaryDirectory() as d:
    src=Path(d)/'r.c'; exe=Path(d)/'r'; src.write_text(c)
    subprocess.run(['gcc','-O2','-I'+str(root/'engine'),str(src),str(root/'engine/preset.c'),'-o',str(exe)],check=True)
    rows=subprocess.check_output([str(exe)],text=True).splitlines()
